checkRuns.command:
mkdir -p test && cat > test/site.test.ts <<'EOF'
import { expect, it } from 'bun:test'
import { ActionError } from 'kay'
import { testSite } from 'kay/test'
import { send } from '../src/routes/contact.kay'

const site = await testSite()

it('thanks a valid message', async () => {
  const result = await site.call(send, { name: ' Ada ', email: 'ada@example.com', message: 'A message long enough to pass.' })

  expect(result.name).toBe('Ada')
})

it('refuses an invalid message with every error', async () => {
  const error = await site.call(send, { name: '', email: 'nope', message: 'short' }).catch(e => e)

  expect(error).toBeInstanceOf(ActionError)
  expect((error as ActionError).data).toEqual({ errors: {
    name: 'Name is required.',
    email: 'Enter a valid email address.',
    message: 'Message must be at least 20 characters.',
  } })
})

it('answers 404 for an unknown book', async () => {
  const page = await site.visit('/books/nope')

  expect(page.status).toBe(404)
  expect(page.html).not.toContain('aria-current')
})
EOF
bun test 2>&1 | tail -8; bun run check
